"""Configuracion general: marca, VERSION y recursos empaquetados.

Contrato:
  VERSION            texto "vX.Y" que se muestra en el pie de pagina y se
                     escribe en el registro de uso. compilar_firmar_empaquetar
                     lo lee de aqui para nombrar el .zip.
  resource_path(rel) -> Path de un recurso junto al programa: en el .exe
                     (PyInstaller) es la carpeta _MEIPASS; en desarrollo es la
                     raiz del proyecto (carpeta que contiene app.py).
  logo_b64(nombre, incrustado) -> base64 del logo en assets/ o el incrustado.
  icono_pagina()     -> imagen PIL del icono de la pestana (o None).

Depende de: (solo biblioteca estandar / terceros)
"""

import base64
import io
import sys
from pathlib import Path


# ============================================================
# RECURSOS Y CONFIGURACION
# ============================================================
def resource_path(relative_path):
    if getattr(sys, "frozen", False):
        base = Path(sys._MEIPASS)
    else:
        # gmya/config.py -> raiz del proyecto (donde estan gmya.ico y
        # assets/), igual que el monolito que vivia en la raiz.
        base = Path(__file__).resolve().parent.parent
    return base / relative_path


ICONO = resource_path("gmya.ico")
FIRMA = "GMYA"
RAZON_SOCIAL = "Giraldo Mosquera y Asociados SAS"
PRODUCTO = "Plataforma de automatización contable"
VERSION = "v6.23"

# Logos en version clara (para fondos oscuros). Si existe la carpeta
# assets junto al aplicativo se usan esos archivos; si no, los incrustados.
LOGO_GMA_B64 = ""
LOGO_NOMBRE_B64 = ""


def logo_b64(nombre_archivo, incrustado):
    ruta = resource_path(f"assets/{nombre_archivo}")
    if ruta.exists():
        return base64.b64encode(ruta.read_bytes()).decode("ascii")
    return incrustado


# Icono de la pestana del navegador. Streamlit no siempre acepta la ruta de
# un .ico, por eso se abre como imagen (Pillow). Si el archivo no esta junto
# al programa (o no se empaqueto con PyInstaller) se usa el mismo icono
# incrustado aqui, asi nunca aparece un emoji.
ICONO_PNG_B64 = ""


def icono_pagina():
    from PIL import Image
    for ruta in (ICONO, resource_path("assets/gmya.png"),
                 resource_path("assets/gmya.ico")):
        try:
            if ruta.exists():
                imagen = Image.open(ruta)
                imagen.load()
                return imagen.convert("RGBA")
        except Exception:
            continue
    try:
        imagen = Image.open(io.BytesIO(base64.b64decode(ICONO_PNG_B64)))
        imagen.load()
        return imagen.convert("RGBA")
    except Exception:
        return None
